head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > initGrid]<br/>GridView 의 데이터, 필터, Column 정보를 포함한 전체 상태를 초기화하고 데이터를 1차원 배열로 반환합니다.",
    "validation" : [
        "initGrid() 메소드는 바인딩된 DataList 의 전체 데이터를 1차원 배열로 반환합니다.",
        "initGrid() 메소드는 DataList 의 전체 데이터를 삭제하지만 DataList 바인딩 자체는 유지됩니다.",
        "initGrid() 메소드는 데이터, 필터, Column 정보를 포함한 GridView 의 전체 상태를 초기화하며, 적용된 필터가 해제됩니다."
    ]
}



scwin.gVar = { "baseData": [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// 바인딩 DataList(9건, 부서 3그룹) + GridView 동적 생성 후, 전제로 [필터 적용] 상태를 구성한다.
//  - 필터 : dept='Sales' (바인딩 DataList 의 setColumnFilter) -> 3건만 표시. initGrid() 후 해제되는지 검증
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 데이터 9건(부서 3그룹) 바인딩 + dept 컬럼 필터(Sales) 적용 -> 3건만 표시\n[절차] (initGrid) 클릭 -> 반환 1차원 배열 확인 후 DataList 데이터 재삽입\n[확인] 반환 1차원 배열 / DataList 데이터 삭제(Row수 0) + 바인딩 유지 / 필터 해제(재삽입 시 전체 9건 표시)"', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 9건 : Sales 3건 + Dev 3건 + QA 3건 (부서 3그룹)
    scwin.gVar.baseData = [
        { "name": "John",  "dept": "Sales", "amount": 100 },
        { "name": "Jane",  "dept": "Sales", "amount": 200 },
        { "name": "Jack",  "dept": "Sales", "amount": 300 },
        { "name": "Mike",  "dept": "Dev",   "amount": 400 },
        { "name": "Amy",   "dept": "Dev",   "amount": 500 },
        { "name": "Alex",  "dept": "Dev",   "amount": 600 },
        { "name": "Tom",   "dept": "QA",    "amount": 700 },
        { "name": "Tina",  "dept": "QA",    "amount": 800 },
        { "name": "Tony",  "dept": "QA",    "amount": 900 }
    ];
    dlt_bind.setJSON(scwin.gVar.baseData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록 (데이터 9건, 부서 3그룹)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    // 전제 : 필터 적용 (바인딩 DataList 의 setColumnFilter) - dept='Sales' 행만 표시(3건)
    dlt_bind.setColumnFilter("dept", "Sales", "and", true);
}



// initGrid 실행 — 전체 상태 초기화 + 데이터 1차원 배열 반환
scwin.btn_initGrid_onclick = function () {
    var bottom = wf_body_bottom.getObj("scwin");

    // 실행 전 : 필터(dept='Sales') 적용으로 표시되는 Row 수 (getRowCount 는 필터 반영 -> 3)
    let filteredRowCount = target1.getRowCount();

    // 전체 상태 초기화 + 데이터 반환
    let result = target1.initGrid();

    setTimeout(function () {
        // [validation 1] 바인딩된 DataList 의 전체 데이터를 1차원 배열로 반환
        bottom.setReturnValue("[반환값] Array 여부 = " + Array.isArray(result) + " / 길이 = " + (result ? result.length : result) + " / 내용 = " + JSON.stringify(result));

        // [validation 2] 데이터 삭제하나 바인딩 자체는 유지
        bottom.setReturnValue("[데이터 삭제 / 바인딩 유지] DataList Row수 = " + dlt_bind.getRowCount() + " / 바인딩 DataList ID = " + target1.getDataListInfo().id);

        // [validation 3] 필터 초기화 : 데이터 재삽입 시 필터 없이 전체(9건) 표시
        dlt_bind.setJSON(scwin.gVar.baseData, false);
        setTimeout(function () {
            bottom.setReturnValue("[필터 초기화] 필터 적용 시 표시 Row수 = " + filteredRowCount + " -> initGrid 후 재삽입 시 표시 Row수 = " + target1.getRowCount() + " (필터 해제로 전체 9건 표시, 잔존 시 3건)");
        }, 200);
    }, 200);
}
